  --primary: #5b48ff;
  --primary-2: #7f6dff;
  --accent: #ff6a4d;
  --success: #13a07a;
  --border: #e6e9f5;
  --shadow: 0 10px 30px rgba(45, 54, 130, 0.08);
  --radius: 16px;
  --container: 1160px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; font-family: Inter, "Plus Jakarta Sans", system-ui, -apple-system, sans-serif; color: var(--text); background: var(--bg); }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(var(--container), 92vw); margin: 0 auto; }
.section { padding: 72px 0; }
.section.alt { background: var(--bg-soft); }
.section.tint { background: var(--bg-tint); }
.badge { display: inline-block; padding: 6px 12px; border-radius: 999px; background: rgba(91,72,255,0.12); color: var(--primary); font-weight: 600; font-size: 12px; }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; border: 0; border-radius: 12px; padding: 12px 18px; font-weight: 600; cursor: pointer; transition: .2s ease; }
.btn.primary { background: linear-gradient(135deg, var(--primary), var(--primary-2)); color: #fff; box-shadow: var(--shadow); }
.btn.primary:hover { transform: translateY(-1px); filter: brightness(1.03); }
.btn.secondary { background: #fff; color: var(--primary); border: 1px solid var(--border); }
.btn.secondary:hover { border-color: var(--primary-2); }
.btn.ghost { background: transparent; border: 1px solid var(--border); color: var(--text); }
.card { background: #fff; border: 1px solid var(--border); border-radius: var(--radius); padding: 24px; box-shadow: var(--shadow); }
.grid { display: grid; gap: 24px; }
.site-header { position: sticky; top: 0; z-index: 30; backdrop-filter: blur(8px); background: rgba(255,255,255,0.88); border-bottom: 1px solid var(--border); }
.nav-wrap { height: 74px; display: flex; align-items: center; justify-content: space-between; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 20px; }
.logo-dot { width: 28px; height: 28px; border-radius: 8px; background: linear-gradient(135deg,var(--primary),#3aa8ff); }
.nav { display: flex; gap: 22px; color: #36405f; font-weight: 500; }
.nav-cta { display: flex; gap: 10px; align-items: center; }
.hero { padding: 80px 0 52px; background: radial-gradient(circle at 80% 10%, rgba(91,72,255,0.15), transparent 45%), radial-gradient(circle at 10% 90%, rgba(127,109,255,0.13), transparent 35%), #fff; }
h1 { font-size: clamp(38px, 6vw, 62px); line-height: 1.05; margin: 0 0 16px; letter-spacing: -0.02em; }
h2 { font-size: clamp(28px, 4vw, 42px); line-height: 1.15; margin: 0 0 12px; letter-spacing: -0.01em; }
.lead { font-size: 20px; color: var(--muted); margin: 0 0 28px; max-width: 760px; }
.sub { color: var(--muted); margin-top: 0; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.logo-row { display: flex; flex-wrap: wrap; gap: 22px; color: #6d7594; font-weight: 600; }
.feature-grid { grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); }
.use-grid { grid-template-columns: repeat(auto-fit, minmax(250px,1fr)); }
.stat-grid { grid-template-columns: repeat(auto-fit, minmax(220px,1fr)); }
.stat { text-align: center; }
.stat strong { display:block; font-size: 42px; color: var(--primary); }
.pricing-grid { grid-template-columns: repeat(auto-fit,minmax(250px,1fr)); }
.plan { position: relative; }
.plan.popular { border: 2px solid var(--primary); }
.plan .price { font-size: 38px; font-weight: 800; margin: 10px 0; }
.plan ul { padding-left: 18px; color: #3c4460; }
.cta-band { border-radius: 24px; padding: 36px; background: linear-gradient(135deg,#2f2a63,#5b48ff); color: #fff; display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; }
.footer { background: #111528; color: #c9d1ee; padding: 48px 0; }
.footer a { color: #fff; opacity: .85; }
.auth-wrap { min-height: 100vh; display: grid; place-items: center; background: linear-gradient(180deg,#f8f9ff,#eef1ff); }
.auth-card { width: min(980px, 94vw); background: #fff; border: 1px solid var(--border); border-radius: 22px; box-shadow: var(--shadow); overflow: hidden; display: grid; grid-template-columns: 1fr 1fr; }
.auth-card.single { grid-template-columns: 1fr; max-width: 520px; }
.auth-panel { padding: 34px; }
.input { width: 100%; padding: 12px 14px; border-radius: 10px; border: 1px solid var(--border); margin: 10px 0 12px; font: inherit; }
.socials { display: grid; gap: 10px; margin: 14px 0; }
.socials button { width: 100%; justify-content: flex-start; }
.divider { display:flex; align-items:center; gap:10px; color:#8a92ab; font-size:12px; margin: 8px 0; }
.divider:before, .divider:after { content:""; height:1px; flex:1; background: var(--border); }
.notice { font-size: 13px; color: #6f7895; }
.cookie-banner { position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%); width: min(860px,94vw); background: #111528; color: #fff; border-radius: 16px; padding: 18px; z-index: 90; box-shadow: var(--shadow); display: none; }
.cookie-banner.active { display: block; }
.cookie-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 10px; }
.modal-backdrop { position: fixed; inset: 0; background: rgba(8,11,26,.52); display: none; place-items: center; z-index: 100; }
.modal-backdrop.open { display: grid; }
.modal { width: min(520px, 92vw); background: #fff; border-radius: 18px; padding: 24px; }
.toggle-row { display:flex; justify-content:space-between; align-items:center; padding: 10px 0; border-bottom: 1px solid var(--border); }
.switch { width: 46px; height: 26px; border-radius: 999px; background: #c4cae5; position: relative; cursor: pointer; transition: .2s; }
.switch:after { content: ""; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; transition: .2s; }
.switch.on { background: var(--primary); }
.switch.on:after { left: 23px; }
.billing-toggle { display: inline-flex; padding: 4px; border:1px solid var(--border); border-radius: 999px; background: #fff; }
.billing-toggle button { padding: 8px 14px; border: 0; background: transparent; border-radius: 999px; cursor:pointer; font-weight: 600; }
.billing-toggle button.active { background: #ecebff; color: var(--primary); }
.range-row { display:flex; gap:12px; align-items:center; flex-wrap: wrap; margin: 16px 0 28px; }
.comparison { width: 100%; border-collapse: collapse; background: #fff; border-radius: 14px; overflow: hidden; }
.comparison th, .comparison td { border: 1px solid var(--border); padding: 12px; text-align: left; font-size: 14px; }
.faq-item { border-bottom: 1px solid var(--border); }
.faq-q { width:100%; text-align:left; background: none; border:0; padding: 16px 0; font-weight: 600; cursor: pointer; }
.faq-a { display:none; color: var(--muted); padding-bottom: 16px; }
.faq-item.open .faq-a { display:block; }
@media (max-width: 860px){
  .nav { display:none; }
  .auth-card { grid-template-columns: 1fr; }
}
